// Generated from canonical approved legal Markdown bytes. Do not edit.
const utf8Decoder = new TextDecoder("utf-8", { fatal: true, ignoreBOM: true });

function decodeUtf8Base64(value) {
  const binary = atob(value);
  const bytes = Uint8Array.from(binary, (character) => character.charCodeAt(0));
  return utf8Decoder.decode(bytes);
}

export const LEGAL_RUNTIME_SOURCES = Object.freeze({
  "/terms": decodeUtf8Base64(""),
  "/en/terms": decodeUtf8Base64(""),
  "/privacy": decodeUtf8Base64(""),
  "/en/privacy": decodeUtf8Base64(""),
  "/legal/tokushoho": decodeUtf8Base64(""),
  "/privacy/foreign-processing": decodeUtf8Base64(""),
  "/en/privacy/foreign-processing": decodeUtf8Base64("")
});
